//! Empirical amino-acid substitution models (v1.1 spec §3.3).
//!
//! A `RateModel` stores the equilibrium frequencies plus a precomputed
//! eigendecomposition of its rate matrix Q (normalized so
//! `-Σ πᵢ qᵢᵢ = 1`, i.e. distances are expected substitutions per site,
//! PHYLIP `protdist` units). `transition_probs(t)` evaluates
//! `P(t) = U·diag(exp(λt))·U⁻¹` without any linear algebra in the engine.
//!
//! The constants in [`jtt_constants`] are generated by
//! `scripts/gen_models.py` from `data/models/jtt.dat` — never hand-edited.

pub mod jtt_constants;

/// A reversible empirical substitution model (v1.1 spec §3.3).
pub struct RateModel {
    /// Model name ("JTT").
    pub name: &'static str,
    /// Number of states (20 for amino-acid models).
    pub n: usize,
    /// Stationary frequencies π, in `PROTEIN_STATES` order.
    pub freqs: [f64; 20],
    eigvals: [f64; 20],
    u: [[f64; 20]; 20],
    u_inv: [[f64; 20]; 20],
}

impl RateModel {
    /// `P(t) = U·diag(exp(λᵢt))·U⁻¹` (v1.1 spec §3.3). Each entry is
    /// clamped to at least `1e-300` so downstream `ln` never sees zero.
    pub fn transition_probs(&self, t: f64) -> [[f64; 20]; 20] {
        let n = self.n;
        let mut d = [0.0_f64; 20];
        for (k, d_k) in d.iter_mut().enumerate().take(n) {
            *d_k = libm::exp(self.eigvals[k] * t);
        }
        let mut p = [[0.0_f64; 20]; 20];
        for (i, row) in p.iter_mut().enumerate().take(n) {
            for (j, cell) in row.iter_mut().enumerate().take(n) {
                let mut acc = 0.0;
                for ((u_ik, d_k), u_inv_k) in self.u[i]
                    .iter()
                    .zip(d.iter())
                    .zip(self.u_inv.iter())
                    .take(n)
                {
                    acc += u_ik * d_k * u_inv_k[j];
                }
                *cell = acc.max(1e-300);
            }
        }
        p
    }

    /// Joint probability `π_x·P_xy(t)` of observing states `x` and `y`
    /// after distance `t`, plus its first two derivatives in `t`.
    ///
    /// Evaluated spectrally as `Σ_k c_k(x)·c_k(y)·λ_k^m·exp(λ_k t)` for
    /// m = 0, 1, 2, where `c` is the spectral coefficient matrix
    /// (`u_inv`'s rows for the protdist-embedded JTT decomposition —
    /// see `data/models/README.md`). This is the arithmetic
    /// `protdist`'s `predict` performs, so the likelihood and Newton
    /// trajectory in `protein_dist` reproduce the oracle bit-near.
    pub(crate) fn site_prob_derivs(&self, x: usize, y: usize, t: f64) -> (f64, f64, f64) {
        let (mut p, mut dp, mut d2p) = (0.0, 0.0, 0.0);
        for m in 0..self.n {
            let q = self.u_inv[m][x] * self.u_inv[m][y] * libm::exp(self.eigvals[m] * t);
            p += q;
            dp += self.eigvals[m] * q;
            d2p += self.eigvals[m] * self.eigvals[m] * q;
        }
        (p, dp, d2p)
    }
}

/// The JTT (Jones, Taylor & Thornton 1992) model (v1.1 spec §3.3).
pub static JTT: RateModel = RateModel {
    name: "JTT",
    n: 20,
    freqs: jtt_constants::FREQS,
    eigvals: jtt_constants::EIGVALS,
    u: jtt_constants::U,
    u_inv: jtt_constants::U_INV,
};
